+                .andExpect(
+                        jsonPath("$.data.violations[0].code")
+                                .value("EXECUTION_SCOPE_NOT_SUPPORTED"))
+                .andExpect(jsonPath("$.data.violations[0].detail.supported").value("BACKTEST"));
